      "entities" : {
        "hashtags" : [ ],
        "symbols" : [ ],
        "user_mentions" : [ ],
        "urls" : [ ]
      },
      "display_text_range" : [
        "0",
        "232"
      ],
      "favorite_count" : "0",
      "in_reply_to_status_id_str" : "1992588612974882874",
      "id_str" : "1992588781564957178",
      "in_reply_to_user_id" : "1981751604463448064",
